export function getLegalCopy(locale: Locale, key: RouteKey): LegalCopy | undefined {
  if (!(key in titles[locale])) return undefined;
  const legalKey = key as LegalKey;
  const labels = ui[locale];
  const contact = `${SITE.legalName}\n${SITE.address.street}\n${SITE.address.postalCode} ${SITE.address.city}\n${SITE.email}\n${SITE.phone}`;
  const detailed = locale === "de" && legalKey !== "imprint" ? germanDetailedPolicies[legalKey] : undefined;
  const sections: LegalSection[] = legalKey === "imprint"
    ? [
        { title: labels.provider, paragraphs: [`${SITE.legalName}\n${SITE.address.street}\n${SITE.address.postalCode} ${SITE.address.city}\nDeutschland`] },
        { title: labels.contact, paragraphs: [`Telefon: ${SITE.phone}\nE-Mail: ${SITE.email}\nWeb: ${SITE.url.replace(/^https?:\/\//, "")}`] },
        { title: registerTitle[locale], paragraphs: [`${SITE.commercialRegisters.map((entry) => `${entry.court}: ${entry.number}`).join("\n")}\nEUID: ${SITE.euid}\nUSt-IdNr.: ${SITE.vatId}`] },
      ]
    : detailed
      ? [...detailed, { title: labels.contact, paragraphs: [contact, labels.contract] }]
      : [
        { title: labels.coverage, paragraphs: [summaries[locale][legalKey]], bullets: actions[locale][legalKey] },
        { title: labels.contact, paragraphs: [contact, labels.contract] },
      ];
  const intro = legalKey === "imprint" ? labels.intro : summaries[locale][legalKey];
  return { eyebrow: labels.eyebrow, title: titles[locale][legalKey], intro, sections, related: related[legalKey] };
}

